    "Для работы офлайн сначала откройте приложение с интернетом. Доступность установки зависит от браузера.": "Барои кор кардан дар интернет, аввал барномаро бо интернет кушоед. Дастрасии ин барнома вобаста ба браузер аст.",
    "Для чего просят оригинал и кто будет его хранить? Обсудите ситуацию со специалистом до передачи.": "Барои чӣ дархост мекунанд ва кӣ онро нигоҳ медорад? Пеш аз интиқол вазъиятро бо мутахассис муҳокима кунед.",
    "Дней в месяц": "Рӯзҳо дар як моҳ",
    "До 10 МБ на файл. Файлы хранятся в браузере на этом устройстве.": "То 10 МБ дар як файл. Файлҳо дар браузер дар ин дастгоҳ нигоҳ дошта мешаванд.",
    "До 10 МБ на файл. Хранятся только в этом браузере. Не загружайте паспортные данные в публичный пилот.": "То 10 МБ дар як файл. Танҳо дар ин браузер нигоҳ дошта мешавад. Маълумоти шиносномаро ба пилоти ҷамъиятӣ бор накунед.",
    "До 10 МБ. Можно выбрать запись с диктофона.": "То 10 МБ. Шумо метавонед аз диктофон сабт кунед.",
    "До 10 МБ. Хранится на этом устройстве. Для публичного пилота используйте вымышленные или обезличенные материалы.": "То 10 МБ. Дар ин дастгоҳ нигоҳ дошта мешавад. Барои парвозгари оммавӣ маводи сохта ё бешахсӣ истифода баред.",
    "До 3 минут. Микрофон включится только с вашего разрешения.": "То се дақиқа. Микрофон танҳо бо иҷозати шумо фаъол мешавад.",
