    "Загрузить серверную версию": "Версияи серверро зеркашӣ кунед",
    "Заданные ключевые слова не найдены. Это не означает, что документ не содержит важных условий.": "Калимаҳои калидии додашуда пайдо нашуданд. Ин маънои онро надорад, ки ҳуҷҷат шартҳои муҳимро дар бар намегирад.",
