    "Записать рассказ": "Ҳикояро сабт кунед",
    "Записаться на встречу, найти занятия русским языком, обсудить документы с куратором. Задачи здесь организационные: индивидуальные требования уточняйте у специалиста.": "Барои мулоқот ба қайд гирифтани маълумот, дарси забони русӣ пайдо кардан, бо куратор дар бораи ҳуҷҷатҳо муҳокима кардан.",
    "Записи восстановлены. Вложения хранятся отдельно.": "Таърихи он барқарор шудааст. Таърифҳо алоҳида нигоҳ дошта мешаванд.",
    "Записи изменились в другой вкладке или на другом устройстве. Сохраните свою копию и загрузите актуальные записи.": "Таҷҳизоти сабт дар як ҷадвали дигар ё дар дастгоҳи дигар тағйир ёфтаанд. Нусхаи худро нигоҳ доред ва сабтҳои навро бор кунед.",
    "Записи на этом устройстве": "сабтҳо дар ин дастгоҳ",
    "Записи плана, семьи, работы и личные черновики сохраняются в вашем аккаунте на сервере. Гостевые записи не переносятся автоматически.": "Ҳисобҳои нақша, оила, кор ва тарҳҳои шахсӣ дар ҳисоби шумо дар сервер нигоҳ дошта мешаванд. Ҳисобҳои меҳмон ба таври худкор интиқол дода намешаванд.",
    "Записи превышают лимит серверного хранилища. Скачайте резервную копию.": "Тасвирҳо аз ҳадди захираи сервер зиёдтар мебошанд. Нусхаи эҳтиётӣ зеркашӣ кунед.",
    "Записи сохраняются на сервере в вашем аккаунте. Гостевые записи не перенесены. Файлы остаются на этом устройстве; на другом устройстве их потребуется прикрепить заново.": "Ин сабтҳо дар сервери ҳисоби шумо нигоҳ дошта мешаванд. сабтҳои меҳмонҳо интиқол дода нашудаанд. Файлҳо дар ин дастгоҳ мемонанд; дар дастгоҳи дигар онҳоро аз нав пайваст кардан лозим аст.",
    "Записи удалены.": "Тасвирҳо нест карда шуданд.",
    "Записывайте согласованные суммы. Расчёт в приложении не подтверждает размер юридически установленного долга.": "Маблағи мувофиқшударо сабт кунед. Ҳисобкунии замима маблағи қарзи қонунӣ тасдиқ намекунад.",
    "Запись больше не существует.": "Ин сабт дигар вуҷуд надорад.",
    "Запись началась. Максимум 3 минуты.": "Тасвир оғоз шуд. 3 дақиқа зиёдтар.",
    "Запись не найдена.": "Навор ёфт нашуд.",
    "Запись недоступна в этом браузере. Используйте готовый аудиофайл или текст.": "Ин сабт дар ин браузер дастрас нест. Файли аудио ё матнро истифода баред.",
    "Запись оказалась пустой. Попробуйте ещё раз.": "Ин сабт холӣ шуд. Боз кӯшиш кунед.",
    "Запись сохранена на устройстве.": "Ин сабт дар дастгоҳ нигоҳ дошта шудааст.",
    "Запись хранится на устройстве.": "Ин сабт дар дастгоҳ нигоҳ дошта мешавад.",
    "Запишите понятное объяснение или вопрос. Не оставляйте непонятные пункты без внимания.": "Шарҳи фаҳмо ё саволро нависед. Нуқтаҳои нофаҳмро беназир нагузоред.",
    "Запишите рассказ и добавьте короткое пояснение для специалиста.": "Ҳикояи худро нависед ва ба мутахассис шарҳи кӯтоҳ илова кунед.",
    "Запишите то, что умеете: профессию, работу с инструментом, пройденный курс или опыт общения с клиентами.": "Дар бораи касби худ, кори худ, омӯзиши худ ё таҷрибаи муштариён нависед.",
    "Запишите условия, которые нужно обсудить до подписания документов.": "Шартҳои пеш аз имзо шудани ҳуҷҷатҳоро нависед.",
