    "Здесь можно составить план, вести смены и выплаты, подготовить обращение, собрать семейные дела и сохранить материалы.": "Дар ин ҷо шумо метавонед нақшае ба нақша гиред, иваз ва пардохтҳо анҷом диҳед, аризаро омода кунед, парвандаҳои оилавӣ ҷамъоварӣ кунед ва маводҳоро захира кунед.",
    "Здесь появятся ваши записи о звонках, встречах и следующих шагах.": "Ин сабти зангҳои шумо, мулоқотҳо ва қадамҳои навбатӣ хоҳад буд.",
    "Здесь — внешние официальные сервисы и организации, не подключённые партнёры «Моста». Язык приёма, стоимость, часы и возможность записи нужно уточнить у них. Ссылки сверены 15.11.2026.": "Дар ин ҷо хадамоти расмии беруна ва ташкилотҳое ҳастанд, ки шарикони пайвастшавии Bridge нестанд. Забони қабул, арзиш, соат ва имконияти сабт бояд аз онҳо мушаххас карда шаванд.",
