    "Изменения остаются в памяти этой вкладки до успешного сохранения. Проверяйте статус вверху и скачайте копию перед закрытием, если сохранение приостановлено.": "Тағйиротҳо дар хотираи ин қолаб мемонанд, то он гоҳ ки ба таври муваффақ нигоҳ дошта шаванд. Агар нигоҳдорӣ қатъ карда шавад, вазъи онро аз боло санҷед ва пеш аз бастани нусхаро зеркашӣ кунед.",
    "Изменения подготовлены. Статус сохранения — вверху экрана.": "Тағйиротҳо омода шудаанд, ҳолати нигоҳдорӣ дар болои экран.",
