    "Инструмент ищет несколько известных формулировок риска. Он не проверяет человека по базам и не даёт оценку «безопасно». Сомнения можно обсудить со специалистом.": "Ин восита якчанд тарзи маълумро меҷӯяд. Он шахсро аз рӯи пойгоҳҳо санҷида намешавад ва баҳодиҳии \"бехатарӣ\" намедиҳад.",
