    "Не добавляйте медицинские сведения и номера документов.": "Маълумоти тиббӣ ва рақамҳои ҳуҷҷатҳоро илова накунед.",
    "Не добавляйте номера банковских карт и документов.": "Номҳои кортҳои бонкӣ ва ҳуҷҷатҳои бонкро илова накунед.",
    "Не добавляйте пароли, номера банковских карт и сведения, которыми не хотите делиться.": "Парольҳо, рақамҳои кортҳои бонкӣ ва маълумоти ғайрииштакро илова накунед.",
    "Не добавляйте паспорт и другие документы личности.": "Пасоси шиноснома ва дигар ҳуҷҷатҳои шахсӣ илова накунед.",
    "Не загружайте настоящие паспортные, медицинские и другие чувствительные сведения в публичный пилот. Любой пользователь этого профиля браузера может открыть записи. Очищать и скачивать копию можно в профиле.": "Маълумоти аслӣ, шифоҳӣ ва дигар маълумоти ҳассосро ба парвандаи ҷамъиятӣ бор накунед. Ҳар як истифодабарандаи ин профили браузер метавонад сабтҳоро кушояд.",
    "Не передавайте пароли и коды из сообщений. Уточните запрос через официальный канал организации.": "Парольҳо ва рамзҳои паёмҳоро надиҳед. Таъкид кунед, ки дархост аз тариқи канали расмии ташкилот аст.",
    "Не принимайте решение только по результату автоматического поиска.": "Танҳо аз рӯи натиҷаи ҷустуҷӯи худкор қарор қабул накунед.",
    "Не удалось выполнить действие.": "Фаъолиятро иҷро карда натавонистанд.",
    "Не удалось загрузить настройки подключения. Подключитесь к интернету и обновите страницу.": "Ба дастгирии пайвастшавӣ ворид шудан натавонистааст. Ба интернет пайваст шавед ва саҳифаро нав кунед.",
    "Не удалось загрузить настройки сервера. Обновите страницу с интернетом.": "Ба танзимоти сервер ворид шудан натавонист. Саҳифаи интернетро нав кунед.",
    "Не удалось записать аудио. Используйте текст или прикрепите файл.": "Наздиккунии аудиоро иҷро накардам. Матнро истифода баред ё файлро ба он пайванд кунед.",
    "Не удалось озвучить фразу. Проверьте доступность русского голоса на устройстве.": "Фразаро баён карда натавонистам. Барои санҷидани дастрасии овози русӣ дар дастгоҳ.",
