    "БЫСТРЫЙ ДОСТУП": "Tezkor qadam",
    "Ба маблағи иҷора чӣ дохил мешавад?": "Nima kiradi?",
    "Без дат учитываются все записи. Выплаты отбираются по дате получения: уточните, за какой период они были.": "Barcha yozuvlar sanadan tashqari hisobga olinadi. To'lovlar olingan sanadan boshlab olinadi: qaysi davrda bo'lganligini aniqlang.",
    "Без лишних поездок": "Yordamsiz sayohatlar",
    "Биёед нишондодҳои ҳисобкунакҳоро нависем.": "Biz hisob-kitoblarning ko'rsatkichlarini o'rnatamiz.",
    "Будет скачан текстовый файл. Вложения нужно скачать отдельно. Проверьте содержимое перед самостоятельной передачей.": "Matn fayli yuklanadi. Ilovalar alohida yuklab olinadi. O'z-o'zidan uzatishdan oldin tarkibini tekshiring.",
    "Будут очищены личные записи V2 на сервере и локальные вложения этого аккаунта. Отправленные в кабинет обращения не удаляются.": "Xizmatxonadagi V2 shaxsiy yozuvlari va ushbu hisobning mahalliy joylashmalari tozalanadi.",
    "Будут очищены личные записи на сервере и локальные вложения этого аккаунта. Отправленные в кабинет обращения не удаляются.": "Serverdagi shaxsiy yozuvlar va ushbu hisobning mahalliy qo'shimchalari o'chirib tashlanadi.",
    "Будут удалены гостевые записи и вложения только второй версии.": "Faqat ikkinchi versiyada qo'shilgan tashrif buyuruvchilarning yozuvlari va qo'shimchalari olib tashlanadi.",
    "Будут удалены запись и её файлы с этого устройства.": "Bu qurilmadagi yozuvlar va fayllar olib tashlanadi.",
    "Будут удалены текст, записи и приложенные к этому черновику материалы из этого устройства.": "Ushbu qurilma matn, yozuvlar va ushbu chizma bilan bog'liq materiallar olib tashlanadi.",
    "Бул суроо боюнча кайда кайрылсам болорун айтып коюңузчу.": "Bu savolga qanday javob berish kerakligini aytaman.",
    "Бул тапшырманы дагы бир жолу түшүндүрүп бериңизчи.": "Bu topshiriqlar bir bor tushuntirilsin.",
    "Бытовая помощь": "Uy yordamlari",
    "В аккаунте уже есть записи. Автоматическая замена гостевыми данными запрещена.": "Hisobotda yozuvlar mavjud. Mehmon ma'lumotlarini avtomatik almashtirish taqiqlanadi.",
    "В меню браузера выберите «Установить приложение» или «Добавить на главный экран».": "Brauzer menusini oching va dasturni o'rnatishni yoki asosiy ekranga qo'shishni tanlang.",
