    "Внесите часы и ставку. Приложение посчитает сумму и поможет сравнить её с выплатами.": "Soat va stavkalarni kiriting. Ilova summani hisoblab chiqadi va pulni to'lovlar bilan taqqoslashga yordam beradi.",
