    "Восстановить": "Tiklash",
    "Восстановить записи": "Yozuvlarni tiklash",
    "Восстановление заменит гостевые записи V2 в этом браузере.": "Tiklash ushbu brauzerdagi V2 mehmon yozuvlarini almashtiradi.",
    "Восстановление заменит гостевые записи в этом браузере.": "Tiklash ushbu brauzerdagi mehmon yozuvlarini almashtiradi.",
