    "Всегда под рукой": "Har doim qoʻlida",
    "Вставьте текст, который хотите понять.": "O'zingiz tushunmoqchi bo'lgan matnni kiriting.",
    "Вся Россия · онлайн": "Butun Rossiya · onlayn",
    "Вы выбираете, что включить в портфолио. Записи добавляете вы; отметка о независимой проверке не присваивается.": "Portfelga nima qo'shishni tanlaysiz. Yozuvlarni qo'shasiz; mustaqil tekshirish belgisi berilmaydi.",
