    "Выберите период, опишите договорённости и приложите свои материалы. Получится понятное досье для специалиста.": "Vaqtni tanlang, kelishuvlarni bayon qiling va materiallaringizni qo'shing. Bu mutaxassis uchun aniq faylni beradi.",
    "Выберите подходящий официальный сервис или организацию и уточните порядок обращения.": "Muvofiq rasmiy xizmat yoki tashkilotni tanlang va murojaat qilish tartibini aniqlang.",
    "Выберите работу осознанно": "Ishni oqilona tanlang",
    "Выберите разделы. Данные семьи, документы и переписка не добавляются автоматически.": "Oila ma'lumotlari, hujjatlar va xat-xabarlar avtomatik ravishda qo'shilmaydi.",
