    "Для работы офлайн сначала откройте приложение с интернетом. Доступность установки зависит от браузера.": "Internetdan tashqarida ishlash uchun dastlab dasturni oching. Qurilma mavjudligi brauzerga bog'liq.",
    "Для чего просят оригинал и кто будет его хранить? Обсудите ситуацию со специалистом до передачи.": "Asl nusxani nima uchun so'rashadi va uni kim saqlaydi?",
    "Дней в месяц": "Oylik kunlar",
    "До 10 МБ на файл. Файлы хранятся в браузере на этом устройстве.": "Faylning 10 MB gacha bo'lishi mumkin. Fayllar ushbu qurilma brauzerida saqlanadi.",
    "До 10 МБ на файл. Хранятся только в этом браузере. Не загружайте паспортные данные в публичный пилот.": "Faylga 10 MBgacha. Bu brauzerda saqlanadi. Pasport ma'lumotlarini ommaviy pilotga yuklama.",
    "До 10 МБ. Можно выбрать запись с диктофона.": "10 MB gacha. O'zingizning diskfoningizdan o'zingizni tanlaysiz.",
    "До 10 МБ. Хранится на этом устройстве. Для публичного пилота используйте вымышленные или обезличенные материалы.": "10 MBgacha. Bu qurilma saqlanadi. Jamoat uchun uchuvchi uchun uydirma yoki nomsiz materiallardan foydalaning.",
    "До 3 минут. Микрофон включится только с вашего разрешения.": "Uch daqiqagacha. Mikrofon faqat sizning ruxsatingiz bilan ishga tushiriladi.",
