    "Добавляйте не более 8 файлов за один раз.": "Bir vaqtning o'zida 8 fayldan ko'p qo'shmang.",
    "Добавляйте только то, что хотите показать собеседнику.": "So'zlashuvchining ko'rsatmoqchi bo'lgan narsani qo'shing.",
