    "Добавьте доверенный контакт": "Ishonchli aloqa qoʻshish",
    "Добавьте документы и только подтверждённые вами даты. Не указывайте предположительные обязательные сроки.": "Hujjatlarni va faqat siz tasdiqlagan sanalarni qo'shing.",
