    "Метавонам тавсияҳои шуморо нависам?": "(Mohammad alayhissalom) \"Mehr-i surʼatlarni oʻzingizga yetkazmoqchimisiz?\" dedilar.",
    "Метавонам тасдиқи пардохтро гирам?": "(Mehsul) bilan birga (ya'ni, o'zlariga) o'xshash narsa (ya'ni, o'zlariga o'xshash narsa) bor.",
