    "Участники": "Ishtirokchilar",
    "Учебные переводы предварительные. Озвучивание использует русские голоса устройства; наличие голоса и работа без сети зависят от браузера. Это разговорные карточки, а не медицинская или юридическая консультация.": "O'quv tarjimalari dastlabki. Ovozlash uskuna rus ovozlarini ishlatadi; ovoz va tarmoqsiz ishlash brauzerga bog'liq. Bu tibbiy yoki yuridik maslahat emas, balki suhbat kartalari.",
