    "Чтобы получать напоминания при закрытом приложении, сохраните события в календарь в разделе «Документы». Фоновые push-уведомления потребуют подключения сервера.": "Ilova yopilganda eslatmalarni olish uchun, hodisalarni kalendarga saqlash uchun Hujjatlar bo'limiga kiring.",
    "Чӣ тавр ба вохӯрӣ бо омӯзгор номнавис шавам?": "Qanday qilib uchrashuv bo'lib o'quvchisi nomunavis tikuvlarni o'tkazadi?",
