    "Это ваш личный семейный план. Совместный доступ с других устройств пока не подключён. Подготовка сводки не открывает доступ к данным.": "Bu sizning shaxsiy oilaviy rejangizdir. Boshqa qurilmalardan qo'shma kirish mavjud emas.",
    "Это ваш план, а не подтверждение правового статуса.": "Bu sizning rejangiz, huquqiy maqomini tasdiqlash emas.",
    "Это ваше описание опыта. Фонд и работодатели его пока не проверяли.": "Bu sizning tajribangiz. Jamg'arma va ish beruvchilar uni tekshirib ko'rmagan.",
