    "Это разбор по ключевым словам и вашим ответам. Он помогает подготовить вопросы, но не определяет законность или безопасность договора.": "Bu asosiy so'zlarni va javoblaringizni o'rganishdir. Bu savollarni tayyorlashda yordam beradi, ammo shartnoma qonuniyligi yoki xavfsizligini belgilamaydi.",
